{
  "units": [
    {
      "quote": "The applicant may not continue to use a previous name after a material name change",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "An applicant is prohibited from continuing to use a previous name after undergoing a material name change, unless specifically permitted by the name change documentation."
    },
    {
      "quote": "unless the name change documentation specifically permits the applicant to continue using that name",
      "scope_quotes": [
        "The applicant may not continue to use a previous name after a material name change"
      ],
      "kind": "exception",
      "meaning": "The prohibition against an applicant continuing to use a previous name after a material name change does not apply if the name change documentation specifically authorizes the applicant to continue using that name."
    },
    {
      "quote": "(see 8 FAM 403.1-6 regarding “known as” names)",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "This parenthetical provides an informational cross-reference to 8 FAM 403.1-6 regarding 'known as' names and establishes no independent rule, duty, or condition."
    },
    {
      "quote": "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "You are required to clear the applicant's pending name, and this obligation applies regardless of whether the name change has been finalized and regardless of whether the passport is being issued at the present time."
    }
  ]
}
